INSERT INTO research.financial_ratio_inputs(ratio_result_id,input_role,fact_id)
SELECT rr.id,map.input_role,sf.id FROM run CROSS JOIN map JOIN research.financial_formula_definitions fd ON fd.formula_key=map.formula_key AND fd.version=1 JOIN research.financial_ratio_results rr ON rr.production_run_id=run.id AND rr.formula_definition_id=fd.id JOIN research.financial_source_facts sf ON sf.production_run_id=run.id AND sf.fact_key=map.fact_key AND sf.period_end=rr.period_end
ON CONFLICT DO NOTHING;
UPDATE research.research_case_work_items SET status='completed',output_payload=jsonb_build_object('production_run_key','ushamart-fy2026-official-v1','validated_facts',(SELECT count(*) FROM research.financial_source_facts sf JOIN research.financial_production_runs r ON r.id=sf.production_run_id WHERE r.run_key='ushamart-fy2026-official-v1'),'validated_ratios',(SELECT count(*) FROM research.financial_ratio_results rr JOIN research.financial_production_runs r ON r.id=rr.production_run_id WHERE r.run_key='ushamart-fy2026-official-v1'),'exceptions',ARRAY['geographic revenue does not reconcile','publication date missing','human review pending']),evidence_refs=jsonb_build_array(jsonb_build_object('source_url','https://ushamartin.com/public/upload/investorrelations/Annual-Report-FY-2025-26.pdf','sha256','c758d7cddee2b3015316f3fafa29c15fbad469209dfbb2ab7164a52181b9822a','pages',ARRAY[240,241,242,243,310,311])) WHERE research_case_id=1 AND work_key='financial_model';
